def words(n):
    n = int(n)
    if n == 0: return 'sıfır'
    s = []
    for val, nm in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q = n // val
        if q:
            if nm == 'bin' and q == 1: s.append('bin')
            else: s.append(_w3(q) + ' ' + nm)
            n = n % val
    if n: s.append(_w3(n))
    return ' '.join(s)
